    public static void rotateRightWorst(int[] nums, int k) {
        // WORST PRACTICE: Missing 'k = k % nums.length'
        // If k is massive, this loop runs indefinitely for no reason!

        // Outermost loop runs exactly k times
        for (int i = 0; i < k; i++) {

            // Save the very last element
            int lastElement = nums[nums.length - 1];

            // Shift every single element to the right by 1
            for (int j = nums.length - 1; j > 0; j--) {
                nums[j] = nums[j - 1];
            }

            // Move the saved element to the front
            nums[0] = lastElement;
        }
    }
}

